	@Test
	void registeredCustomConfigurationFieldsAndNamespacesRoundTripThroughTheEditor() throws Exception {
		RepositoryFactory factory = new RepositoryFactory() {
			@Override
			public String getRepositoryType() {
				return CustomConfig.TYPE;
			}

			@Override
			public RepositoryImplConfig getConfig() {
				return new CustomConfig();
			}

			@Override
			public Repository getRepository(RepositoryImplConfig config) {
				throw new AssertionError("Editing configuration must not instantiate a repository");
			}
		};
		RepositoryRegistry.getInstance().add(factory);
		try {
			RepositoryManager manager = mock(RepositoryManager.class);
			when(manager.hasRepositoryConfig("memory")).thenReturn(true);
			CustomConfig custom = new CustomConfig();
			custom.value = "kept custom setting";
			when(manager.getRepositoryConfig("memory")).thenReturn(new RepositoryConfig("memory", custom));
			MockHttpServletRequest request = new MockHttpServletRequest("GET", "/memory/config");
			request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);

			String turtle = column(run(manager, request), "configuration");
			assertThat(turtle).contains("@prefix custom:", "kept custom setting");
			MockHttpServletResponse saved = run(manager, post(turtle, "save"));

			assertThat(saved.getStatus()).isEqualTo(200);
			ArgumentCaptor<RepositoryConfig> configuration = ArgumentCaptor.forClass(RepositoryConfig.class);
			verify(manager).addRepositoryConfig(configuration.capture());
			assertThat(((CustomConfig) configuration.getValue().getRepositoryImplConfig()).value)
					.isEqualTo("kept custom setting");
		} finally {
			RepositoryRegistry.getInstance().remove(factory);
		}
	}

	@Test
	void persistedConfigurationIsNeverReplacedByAProxyCacheNotModifiedResponse() throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		when(manager.getRepositoryConfig("memory")).thenReturn(new RepositoryConfig("memory", "Current",
				new SailRepositoryConfig(new MemoryStoreConfig(true))));
		ProxyRepositoryServlet proxy = new ProxyRepositoryServlet();
		proxy.setRepositoryManager(manager);
		RepositoryInfo info = new RepositoryInfo();
		info.setId("memory");
		proxy.setRepositoryInfo(info);
		proxy.init(TestServletConfig.withParams("memory", "default-command", "/config", "cookie-max-age", "300",
				"/config", "org.eclipse.rdf4j.workbench.commands.ConfigServlet"));
		try {
			MockHttpServletRequest request = new MockHttpServletRequest("GET", "/memory/config");
			request.setPathInfo("/config");
			request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
			request.addHeader("If-Modified-Since", Long.MAX_VALUE);
			MockHttpServletResponse response = new MockHttpServletResponse();

			proxy.service(request, response);

			assertThat(response.getStatus()).isEqualTo(200);
			assertThat(response.getHeader("Last-Modified")).isNull();
			assertThat(response.getHeaders("Cache-Control")).anyMatch(value -> value.contains("no-store"));
			assertThat(column(response, "configuration")).contains("Current");
		} finally {
			proxy.destroy();
		}
	}

	@Test
	void editorLoadsTheExistingRepositoryConfigurationAsTurtle() throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		RepositoryConfig config = new RepositoryConfig("memory", "Saved title",
				new SailRepositoryConfig(new MemoryStoreConfig(true)));
		when(manager.getRepositoryConfig("memory")).thenReturn(config);
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/memory/config");
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);

		MockHttpServletResponse response = run(manager, request);

		assertThat(response.getStatus()).isEqualTo(200);
		assertThat(response.getHeaders("Cache-Control")).anyMatch(value -> value.contains("no-store"));
		String turtle = column(response, "configuration");
		RepositoryConfig loaded = RepositoryConfigUtil.getRepositoryConfig(
				Rio.parse(new StringReader(turtle), "urn:config:", RDFFormat.TURTLE), "memory");
		assertThat(loaded.getTitle()).isEqualTo("Saved title");
		assertThat(((MemoryStoreConfig) ((SailRepositoryConfig) loaded.getRepositoryImplConfig()).getSailImplConfig())
				.getPersist()).isTrue();
	}

