	private static String nestedConfiguration(boolean legacy) {
		if (legacy) {
			return """
					@prefix rep: <http://www.openrdf.org/config/repository#> .
					@prefix sr: <http://www.openrdf.org/config/repository/sail#> .
					@prefix sail: <http://www.openrdf.org/config/sail#> .
					@prefix ms: <http://www.openrdf.org/config/sail/memory#> .
					@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
					[] a rep:Repository; rep:repositoryID "memory"; rdfs:label "Nested configuration";
					  rep:repositoryImpl [ rep:repositoryType "openrdf:SailRepository";
					    sr:sailImpl [ sail:sailType "rdf4j:SchemaCachingRDFSInferencer";
					      sail:delegate [ sail:sailType "openrdf:MemoryStore"; ms:persist true ] ] ] .
					""";
		}
		return """
				@prefix config: <tag:rdf4j.org,2023:config/> .
				@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
				[] a config:Repository; config:rep.id "memory"; rdfs:label "Nested configuration";
				  config:rep.impl [ config:rep.type "openrdf:SailRepository";
				    config:sail.impl [ config:sail.type "rdf4j:SchemaCachingRDFSInferencer";
					  config:delegate [ config:sail.type "openrdf:MemoryStore"; config:mem.persist true ] ] ] .
				""";
	}

	private static MockHttpServletResponse run(RepositoryManager manager, MockHttpServletRequest request)
			throws Exception {
		TransformationServlet servlet = (TransformationServlet) Class
				.forName("org.eclipse.rdf4j.workbench.commands.ConfigServlet")
				.getConstructor()
				.newInstance();
		servlet.setRepositoryManager(manager);
		RepositoryInfo info = new RepositoryInfo();
		info.setId("memory");
		servlet.setRepositoryInfo(info);
		servlet.init(TestServletConfig.withParams("config", "cookie-max-age", "300"));
		try {
			MockHttpServletResponse response = new MockHttpServletResponse();
			servlet.service(request, response);
			return response;
		} finally {
			servlet.destroy();
		}
	}

	private static String column(MockHttpServletResponse response, String name) throws Exception {
		List<JsonNode> records = response.getContentAsString()
				.lines()
				.filter(line -> !line.isBlank())
				.map(JSON::readTree)
				.toList();
		List<String> vars = new ArrayList<>();
		records.stream()
				.filter(record -> "vars".equals(record.path("type").asText()))
				.forEach(record -> record.path("values").forEach(value -> vars.add(value.asText())));
		int index = vars.indexOf(name);
		assertThat(index).as("%s column in %s", name, vars).isGreaterThanOrEqualTo(0);
		return records.stream()
				.filter(record -> "rows".equals(record.path("type").asText()))
				.map(record -> record.path("values").get(0).get(index).path("value").asText())
				.findFirst()
				.orElse(null);
	}

	private static final class CustomConfig extends AbstractRepositoryImplConfig {
		private static final String TYPE = "test:WorkbenchCustomConfiguration";
		private static final IRI SETTING = SimpleValueFactory.getInstance().createIRI("urn:custom:", "setting");
		private String value;

		private CustomConfig() {
			super(TYPE);
		}

		@Override
		public Resource export(Model model) {
			Resource node = super.export(model);
			model.setNamespace("custom", "urn:custom:");
			model.add(node, SETTING, SimpleValueFactory.getInstance().createLiteral(value));
			return node;
		}

		@Override
		public void parse(Model model, Resource node) {
			super.parse(model, node);
			value = Models.objectLiteral(model.filter(node, SETTING, null)).orElseThrow().getLabel();
		}
	}
